function highlight(){for(let svg of document.querySelectorAll('.graph-panel svg')){let id=hover||selected,connected=new Set([id]);for(let e of svg.querySelectorAll('.edge'))if(e.dataset.a===id||e.dataset.b===id){connected.add(e.dataset.a);connected.add(e.dataset.b)}for(let n of svg.querySelectorAll('.node')){n.classList.toggle('dim',!!id&&!connected.has(n.dataset.id));n.classList.toggle('active-node',!!id&&n.dataset.id===id)}for(let e of svg.querySelectorAll('.edge')){let active=!!id&&(e.dataset.a===id||e.dataset.b===id);e.classList.toggle('dim',!!id&&!active);e.classList.toggle('active-edge',active)}}}function clearFocus(){selected=null;hover=null;inspect();highlight()}function focus(id){selected=id;hover=null;inspect();highlight()}function inspect(){let box=$('#inspector');if(!selected){box.innerHTML='<span class="kicker">NODE INSPECTOR</span><h3>노드를 선택하세요</h3><p>권역·연도별 키워드와 감정 지표, 연결된 이웃을 살펴볼 수 있습니다.</p>';return}let [region,year]=selected.split('-'),i=data.info[selected],neighbors=new Set();for(let key of graphKeys())for(let e of graphVisible(data.graphs[key]).edges){if(e.a===selected)neighbors.add(e.b);if(e.b===selected)neighbors.add(e.a)}box.innerHTML=`<span class="kicker">NODE INSPECTOR</span><h3>${region} · ${year}</h3><p>${esc(i?.mood||'')}</p><h4>TF-IDF TOP 3 키워드</h4><div class="keywords">${esc(i?.keywords||'—')}</div><dl><dt>연평균 복합점수</dt><dd>${Number.isFinite(i?.score)?i.score.toFixed(1):'—'} / 100</dd><dt>긍정비율</dt><dd>${Number.isFinite(i?.positive)?i.positive.toFixed(1):'—'}%</dd><dt>대표감정</dt><dd>${esc(i?.emotion||'—')}</dd><dt>직접 연결된 이웃</dt><dd>${neighbors.size}개</dd></dl><h4>이웃 노드</h4><div id="neighbors">${[...neighbors].sort().map(n=>`<button data-id="${esc(n)}">${esc(n)}</button>`).join('')||'<p>현재 필터에서 연결 없음</p>'}</div>`;box.querySelector('#neighbors').onclick=e=>{let b=e.target.closest('button');if(b)focus(b.dataset.id)}}
