function setupCharts(){for(let r of Object.keys(colors))$('#chartRegions').insertAdjacentHTML('beforeend',`<button class="region-toggle active" data-region="${r}" style="--c:${colors[r]}"><i></i>${r}</button>`);$('#chartRegions').onclick=e=>{let b=e.target.closest('button');if(!b)return;let r=b.dataset.region;chartRegions.has(r)?chartRegions.delete(r):chartRegions.add(r);b.classList.toggle('active',chartRegions.has(r));chart()};document.querySelectorAll('.metric').forEach(b=>b.onclick=()=>{metric=b.dataset.metric;document.querySelectorAll('.metric').forEach(x=>x.classList.toggle('active',x===b));chart()});for(let n of emotionNames)$('#songEmotion').insertAdjacentHTML('beforeend',`<option>${n}</option>`);$('#emotionLegend').innerHTML=emotionNames.map(n=>`<span><i style="background:${emotionColors[n]}"></i>${n}</span>`).join('');chart();emotionChart();versionCards()}
function chart(){let svg=$('#lineChart');svg.innerHTML='';const x0=65,x1=975,y0=38,y1=336,X=y=>x0+(y-1991)*(x1-x0)/34,Y=v=>y1-(v-(metric==='score'?-100:0))*(y1-y0)/(metric==='score'?200:100);for(let [a,b,label] of [[1991,1999,'1990s'],[2000,2009,'2000s'],[2010,2019,'2010s'],[2020,2025,'2020s']]){let left=X(a)-(a===1991?0:(x1-x0)/68),right=X(b)+(b===2025?0:(x1-x0)/68);el('rect',{x:left,y:y0,width:right-left,height:y1-y0,fill:a===2000||a===2020?'#ffffff07':'#d8fa8a0b'},svg);let t=el('text',{x:left+8,y:55,fill:'#79918e','font-size':12},svg);t.textContent=label}for(let v of metric==='score'?[-100,-50,0,50,100]:[0,25,50,75,100]){let yy=Y(v);el('line',{x1:x0,y1:yy,x2:x1,y2:yy,stroke:'#4b666a','stroke-dasharray':'3 7'},svg);let t=el('text',{x:5,y:yy+4,fill:'#a6b9b7','font-size':12},svg);t.textContent=v+(metric==='positive'?'%':'')}for(let year of [1991,2000,2010,2020,2025]){let t=el('text',{x:X(year),y:364,fill:'#a6b9b7','font-size':12,'text-anchor':'middle'},svg);t.textContent=year}for(let r of Object.keys(colors)){if(!chartRegions.has(r))continue;let pts=[];for(let year=1991;year<=2025;year++){let v=data.info[r+'-'+year]?.[metric];if(Number.isFinite(v))pts.push([year,v])}el('polyline',{points:pts.map(([y,v])=>`${X(y)},${Y(v)}`).join(' '),fill:'none',stroke:colors[r],'stroke-width':3.2,'stroke-linejoin':'round','stroke-linecap':'round'},svg);for(let [year,v] of pts){let c=el('circle',{cx:X(year),cy:Y(v),r:4,fill:colors[r],stroke:'#112830','stroke-width':1},svg),t=el('title',{},c);t.textContent=`${r} · ${year} · ${metric==='score'?'연평균 복합점수':'긍정비율'} ${v.toFixed(1)}${metric==='positive'?'%':''}`}}}
function emotionChart(){let box=$('#emotionChart');box.innerHTML='';for(let r of Object.keys(colors)){let songs=data.songs.filter(s=>s.region===r),avg=Object.fromEntries(emotionNames.map(n=>[n,songs.reduce((v,s)=>v+s.emotions[n],0)/songs.length])),total=emotionNames.reduce((v,n)=>v+avg[n],0);let row=document.createElement('div');row.className='emotion-row';row.innerHTML=`<b>${r}</b><div class="emotion-bar">${emotionNames.map(n=>`<span style="width:${avg[n]/total*100}%;background:${emotionColors[n]}" title="${r} · ${n} 평균 ${avg[n].toFixed(1)}%"></span>`).join('')}</div><strong>${songs.length}곡</strong>`;box.append(row)}let groups=Object.keys(colors).map(r=>({r,songs:data.songs.filter(s=>s.region===r)})),count=(r,e)=>groups.find(g=>g.r===r).songs.filter(s=>s.emotion===e).length,avg=r=>groups.find(g=>g.r===r).songs.reduce((v,s)=>v+s.score,0)/175,pos=r=>groups.find(g=>g.r===r).songs.filter(s=>s.polarity==='긍정').length/175*100;$('#findings').innerHTML=[['한국',`슬픔이 주요감정인 곡 ${count('한국','슬픔')}곡`],['일본',`슬픔 주요감정 ${count('일본','슬픔')}곡 · 2020년대 평균 점수 +2.4`],['나이지리아',`평균 복합점수 +${avg('나이지리아').toFixed(1)} · 긍정 곡 ${pos('나이지리아').toFixed(1)}%`],['미국',`분노 주요감정 ${count('미국','분노')}곡 · 연평균 점수 장기 하락`],['유럽','신뢰 감정 점수 평균 19.6%'],['캐나다','해설 노트의 다크 R&B 흐름과 함께 보세요']].map(([r,v])=>`<div><b style="color:${colors[r]}">${r}</b><p>${v}</p></div>`).join('')}
function versionCards(){let picks=[['캐나다',1991,'Beauty and the Beast'],['일본',1991,'雨音']];$('#versionCards').innerHTML=picks.map(([r,y,title])=>{let s=data.songs.find(x=>x.region===r&&x.year===y&&x.title===title);if(!s)return '';return `<article><div class="version-head"><span>${r} · ${y}</span><h4>${esc(s.title)}</h4><small>${esc(s.artist)}</small></div><div class="version-pair"><div><span>TF-IDF / 가사의 어휘</span><strong>${esc(s.keywords)}</strong><p>해당 곡에서 추출한 핵심 키워드 3개</p></div><div><span>SENTIMENT / 가사의 감정</span><strong>${s.score>0?'+':''}${s.score.toFixed(1)}점</strong><p>${esc(s.polarity)} · 주요감정 ${esc(s.emotion)}</p></div></div></article>`}).join('')}
function songs(){let q=$('#songSearch').value.trim().toLocaleLowerCase(),r=$('#songRegion').value,y=$('#songYear').value,p=$('#songPolarity').value,e=$('#songEmotion').value,sort=$('#songSort').value;let a=data.songs.filter(s=>(r==='전체'||s.region===r)&&(y==='전체'||s.year===+y)&&(p==='전체'||s.polarity===p)&&(e==='전체'||s.emotion===e)&&(!q||[s.title,s.artist,s.keywords].some(x=>x.toLocaleLowerCase().includes(q))));if(sort==='scoreDesc')a.sort((x,y)=>y.score-x.score);else if(sort==='scoreAsc')a.sort((x,y)=>x.score-y.score);else if(sort==='title')a.sort((x,y)=>x.title.localeCompare(y.title,'ko'));else a.sort((x,y)=>x.year-y.year||x.region.localeCompare(y.region,'ko')||x.rank-y.rank);$('#songRows').innerHTML=a.slice(0,songLimit).map(s=>`<tr data-id="${s.id}" tabindex="0" aria-label="${esc(s.title)} 상세 보기"><td>${s.year}</td><td>${s.region}</td><td>${esc(s.title)}<small>${esc(s.artist)}</small></td><td>${esc(s.keywords)}</td><td>${s.polarity}</td><td>${s.emotion}</td><td>${s.score>0?'+':''}${s.score.toFixed(1)}</td></tr>`).join('');$('#songCount').textContent=`${a.length.toLocaleString()}곡 중 ${Math.min(a.length,songLimit)}곡 표시`;$('#moreSongs').hidden=a.length<=songLimit;$('#songRows').querySelectorAll('tr').forEach(row=>row.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();openSong(row.dataset.id)}})}
function openSong(id){let s=data.songs.find(x=>x.id===id);if(!s)return;$('#dialogBody').innerHTML=`<span class="kicker">SONG PROFILE / ${s.region} · ${s.year}</span><h2 id="dialogTitle">${esc(s.title)}</h2><p class="dialog-artist">${esc(s.artist)}</p><div class="dialog-stats"><div><span>TF-IDF TOP 3</span><strong>${esc(s.keywords)}</strong></div><div><span>복합점수</span><strong>${s.score>0?'+':''}${s.score.toFixed(1)} / 100</strong></div><div><span>분류 · 주요감정</span><strong>${s.polarity} · ${s.emotion}</strong></div></div><h3>8대 감정 분포</h3><div class="dialog-emotions">${emotionNames.map(n=>`<div><span>${n}</span><div class="meter"><i style="width:${Math.min(100,Math.max(0,s.emotions[n]))}%;background:${emotionColors[n]}"></i></div><b>${s.emotions[n].toFixed(1)}%</b></div>`).join('')}</div><p class="dialog-note">곡별 병합 감정 데이터의 원본 점수입니다.</p>`;$('#songDialog').showModal()}

